import sys;sys.path.insert(0,'/workspace/seo/b8')
from common import *
S={};CC=["iLovePDF","Smallpdf","Sejda"]
G=lambda rows:["Glossary",{"table":[["Term","Meaning"]]+rows}]
def T(key,title,desc,secs,cmp,faq,rel,faqKw=None):
    E(S,key,title=title,desc=desc,compareTitle="{tool}: {brand} vs iLovePDF, Smallpdf and Sejda",compareCols=CC,
      sections=secs+[["Privacy",PDFPRIV],["Related tools",["[%s](/%s/)"%(n,s) for n,s in rel]]],compare=CB(cmp),faq=faq,related=[s for _,s in rel])
    if faqKw:S[key]["faqKw"]=faqKw
# ---------- CROP ----------
T("crop","Crop PDF – Auto Crop White Margins or Set mm, Free",
 "Crop PDF pages free: auto crop white margins with padding, or trim exact mm from each side, on all or selected pages. No upload, no sign-up.",
 [["Crop PDF pages online, automatically or precisely",
   "Crop PDF trims the edges of PDF pages. Use **Auto crop** to remove white margins around the content automatically, with a little padding so nothing feels cramped, or switch to **Manual** to cut an exact number of millimetres from the top, right, bottom and left. You can crop every page or only a range such as 2-10, and the result is a new PDF – your original file is not changed.",
   "Cropping is ideal for reading PDFs on a phone or e-reader (wide margins waste screen space), preparing figures and diagrams for slides, removing scanner borders and black edges, cutting printer's marks from print-ready files, and tidying screenshots that were saved as PDF."],
  ["Auto crop: trim white margins",
   "Auto crop renders each page on your device, finds the outermost non-white pixels, and sets the crop box just outside them plus the padding you choose (3 mm by default). With **Same crop box on every page** ticked, the tool uses the smallest margin found across all selected pages, so every page keeps the same size and content never jumps around when you flip pages – best for books and reports. Untick it to crop each page tightly to its own content, which suits figure collections and scanned receipts of different sizes.",
   "Pages that are rotated in the file are left as they are in auto mode, and completely blank pages are skipped."],
  ["Manual crop in millimetres",
   {"table":[["You want to…","Set"],["Remove a 1 cm scanner border","10 mm on every side"],["Cut printer's crop marks from an A4 file with 3 mm bleed","Measure the marks; often 10–15 mm per side"],["Keep only the top half of a page","Bottom = half the page height (148 mm for A4)"],["Remove a header band","Top = height of the header"]]},
   "One millimetre is about 2.83 PDF points. If the margins you enter add up to more than the page width or height, you will see an error naming the page, so nothing is cropped by mistake."],
  ["How to crop a PDF for free",
   {"steps":["Drop the PDF on this page.","Choose Auto crop (and padding) or Manual margins in mm.","Optionally type a page range such as 1-3,5.","Press Crop and download the cropped PDF."]}],
  ["Is cropping permanent?",
   "PDF cropping works by changing the page's visible area – the crop box, media box, trim box and bleed box are all set to the new size, so every viewer and printer shows the cropped page. The content outside the box is hidden, not erased, which keeps quality perfect and the operation lossless. If you need hidden content to be truly gone (for example, confidential notes in a margin), use [Redact PDF](/redact-pdf/) or [Flatten PDF](/flatten-pdf/) in *all content* mode afterwards."],
  ["Crop PDF to JPG",
   "To get a cropped picture rather than a PDF – a figure for a presentation or a website – crop here first, then convert the result with [PDF to JPG](/pdf-to-jpg/) or [PDF to PNG](/pdf-to-png/). Because the crop box is respected, the images contain only the area you kept."],
  ["Crop vs resize",
   "Cropping removes edges and makes the page smaller. [Resize PDF](/resize-pdf/) changes the paper size – for example, from Letter to A4 – by scaling the content to fit. If a document must be a specific paper size after cropping, crop first and then resize."],
  ["Tips for the best result",
   {"list":["For books, keep *same crop box* on so pages line up; for mixed documents, turn it off.",
    "Add 2–5 mm padding to avoid text touching the edge on e-readers.",
    "Scanned pages with grey backgrounds or dark borders may not count as ‘white’; use manual crop or clean the scan first.",
    "Crop only the pages that need it by entering a range – covers often have different margins.",
    "Check the first and last page after cropping: page numbers in the footer are content too and will be kept."]}],
  ["Crop PDF online vs desktop software",
   "Desktop editors can crop pages, but usually require a paid licence. Most online croppers upload your file to a server. This tool gives you auto and manual cropping for free, entirely in your browser – useful for contracts, drawings and other files you would rather not upload."],
  G([["Crop box","The visible area of a page in a PDF"],["Media box","The full size of the page's ‘paper’"],["Bleed / trim box","Print-production areas; set to the crop size here"],["Padding","Extra space kept around content in auto crop"]])],
 [["Auto crop white margins","Yes"],["Exact margins in mm","Yes"],["Page range","Yes"],["Same box on all pages option","Yes"]],
 [Q("How do I crop a PDF?","Drop the PDF, choose auto crop or manual margins in mm, and download the cropped file."),
  Q("Can I crop PDF pages for free?","Yes, with no sign-up, watermark or limit."),
  Q("Can I auto crop a PDF?","Yes, auto crop removes white margins automatically with optional padding."),
  Q("Can I crop only some pages?","Yes, type a range such as 2-10."),
  Q("Does cropping reduce quality?","No, it only changes the visible area; content is not re-rendered."),
  Q("Is cropped content deleted?","It is hidden. Use Redact PDF to remove it permanently."),
  Q("How do I crop a PDF to JPG?","Crop here, then convert with PDF to JPG."),
  Q("Is my PDF uploaded?","No, cropping runs in your browser.")],
 [("Resize PDF","resize-pdf"),("PDF to JPG","pdf-to-jpg"),("Redact PDF","redact-pdf"),("Split PDF pages in half","split-pdf-pages-in-half"),("Rotate PDF","rotate-pdf")])
# ---------- GRAYSCALE ----------
T("grayscale","Convert PDF to Grayscale or Black & White Free",
 "Convert PDF to grayscale or pure black and white with an adjustable threshold. Three quality levels. Free, no upload, no sign-up, works offline.",
 [["Convert a PDF to grayscale or black and white",
   "This tool removes colour from a PDF. **Grayscale** turns every colour into a matching shade of grey – the look of a good black-and-white photocopy, keeping photos and charts readable. **Black & white** goes further and turns every pixel pure black or pure white using a threshold you control, which gives crisp, high-contrast pages for text documents, forms and signatures, and the smallest files for scans.",
   "Common reasons: a print shop or court filing system requires grayscale, you want to print without using colour ink, a coloured background makes a scan hard to read, or you need to shrink a colourful scanned document."],
  ["Grayscale vs black and white",
   {"table":[["","Grayscale","Black & white"],["Colours","256 shades of grey","Only black and white"],["Photos","Keep detail","Become harsh, posterised"],["Text scans","Good","Sharpest, removes paper tint"],["File size","Smaller than colour","Usually smallest"],["Best for","Mixed documents, reports","Contracts, forms, letters, receipts"]]},
   "If you are unsure, start with grayscale. Use black and white when the pages are mostly text and you want them to look like a clean fax or laser print."],
  ["Choosing the black & white threshold",
   "Each pixel's brightness (0 = black, 255 = white) is compared with the threshold. The default of 160 works for most office documents. Raise it (180–200) if light or thin text disappears; lower it (120–140) if grey paper, stains or a coloured background turn into black speckles. Run it once, check the result, and adjust – it only takes seconds."],
  ["Quality levels",
   {"table":[["Level","Render scale","Use"],["High","2× (≈144 dpi)","Printing, small text"],["Medium","1.5× (≈108 dpi)","Screen reading, e-mail"],["Small file","1× (72 dpi)","Smallest size; large text only"]]}],
  ["How to convert a PDF to grayscale",
   {"steps":["Drop the PDF.","Choose Grayscale or Black & white (and threshold).","Pick a quality level.","Convert and download."]}],
  ["What happens to text",
   "To guarantee every colour is removed – including colours inside images, gradients, transparency and embedded graphics – each page is rendered and saved as an image. The pages look exactly like the original in grey, but text is no longer selectable or searchable. If you need searchable text, run [OCR PDF](/ocr-pdf/) on the result, which adds an invisible text layer back. Keep your colour original for editing."],
  ["Printing in grayscale without converting",
   "Most print dialogs have a *grayscale* or *black and white* option, which is enough for one-off printing at home. Converting the file is better when you send it to someone else, upload it to a portal that rejects colour, want consistent results on any printer, or need a smaller file."],
  ["Can a grayscale PDF be turned back into colour?",
   "No – the colour information is removed. There is no reliable way to restore the original colours from a grey version, so always keep the colour original."],
  ["Convert PDF to grayscale online vs desktop software",
   "Desktop PDF suites offer colour conversion in their print-production tools, usually in paid editions. Most online converters upload your document first. Here, conversion runs in your browser, is free, and includes a true black-and-white mode that many tools lack."],
  G([["Grayscale","Image made only of shades of grey"],["Black & white / monochrome","Image with only pure black and pure white pixels"],["Threshold","Brightness level that decides black or white"],["DPI","Dots per inch; higher means sharper and larger files"]])],
 [["True black & white mode","Yes"],["Adjustable threshold","Yes"],["Quality levels incl. 200 dpi","4"]],
 [Q("How do I convert a PDF to grayscale?","Drop the PDF, choose Grayscale, pick a quality and download."),
  Q("How do I convert a PDF to black and white, not grayscale?","Choose Black & white and adjust the threshold."),
  Q("Is it free?","Yes, with no sign-up or watermark."),
  Q("Will text stay selectable?","No, pages are rendered as images; run OCR to make them searchable again."),
  Q("Does grayscale make the file smaller?","Usually, especially for colour scans; black & white is often smallest."),
  Q("Can I convert grayscale back to colour?","No, the colour information is gone."),
  Q("What threshold should I use?","Start at 160; raise it if text vanishes, lower it if backgrounds turn black."),
  Q("Is my PDF uploaded?","No, conversion runs on your device.")],
 [("OCR PDF","ocr-pdf"),("Compress PDF","compress-pdf"),("Deskew PDF","deskew-pdf"),("Flatten PDF","flatten-pdf"),("PDF to JPG","pdf-to-jpg")],
 faqKw=[Q("How can I convert a PDF file to 200 dpi grayscale?","Choose Grayscale and the Print (200 dpi) quality level. Every page is rendered at 200 dpi in shades of grey and saved as a new PDF.")])

# ---------- FLATTEN ----------
T("flatten","Flatten PDF – Lock Form Fields & Annotations Free",
 "Flatten PDF forms and annotations so they cannot be edited: flatten form fields only, or all content into page images. Free, no upload, no sign-up.",
 [["What does it mean to flatten a PDF?",
   "Flattening merges interactive or layered parts of a PDF – fillable form fields, check boxes, drop-downs, comments, stamps and drawings – into the page itself. The document looks the same, but those elements stop being separate editable objects. A flattened form shows the answers as ordinary page content that cannot be changed by clicking into a field, and it prints and displays the same in every viewer.",
   "People flatten PDFs before sending completed applications, contracts or tax forms, before archiving, when a portal rejects files with form fields, and when filled-in answers disappear or look different in another app."],
  ["Two flatten modes",
   {"table":[["Mode","What happens","Text selectable?","Best for"],["Form fields","Each field's current value is drawn into the page and the field is removed","Yes","Completed forms, applications"],["All content","Every page is rendered and saved as an image","No (run OCR to restore)","Maximum lock-down, mixed annotations, odd viewer issues"]]},
   "Start with *Form fields*: it keeps the file small and text searchable. Use *All content* when annotations, layers or unusual form technology still appear editable or render differently across apps."],
  ["How to flatten a PDF for free",
   {"steps":["Fill in the form first, in any PDF app or with [Fill PDF form](/fill-pdf-form/).","Drop the PDF here.","Choose Form fields or All content.","Press Flatten and download."]}],
  ["How to flatten a PDF so it cannot be edited",
   "After flattening, form answers can no longer be changed by typing into fields. Bear in mind that any PDF can still be modified with an editor – flattening prevents accidental and casual changes, not determined tampering. For stronger protection, add a password with editing disabled using [Protect PDF](/protect-pdf/), and for proof of integrity use a certificate-based digital signature."],
  ["Does flattening decrease quality?",
   "*Form fields* mode does not touch the rest of the page, so quality is identical. *All content* mode renders pages at about 144 dpi with high JPEG quality, which looks sharp on screen and in normal printing, but text becomes part of an image and the file can grow for text-heavy documents. Use it when appearance matters more than size or searchability."],
  ["Flattening a large PDF",
   "Form-field flattening is quick even for long documents. All-content mode renders every page, so a 200-page file takes longer and the output may be larger; you can run [Compress PDF](/compress-pdf/) afterwards. A progress counter shows which page is being processed."],
  ["Why answers vanish without flattening",
   "Some viewers, mobile apps and print drivers do not display form field values correctly, especially when fields use custom fonts or scripts. The person receiving your form may see empty boxes. Flattening draws the values into the page so everyone sees the same thing."],
  ["Flatten PDF online vs desktop software",
   "Desktop editors can flatten through print-to-PDF or preflight tools, often in paid versions. Online services usually require uploading your completed form – including personal details like ID numbers and addresses. This tool flattens on your device, for free."],
  G([["Form field","An interactive box, check box or list in a PDF form"],["Annotation","A comment, highlight, stamp or drawing layered on a page"],["Appearance stream","The visual drawing of a field's value"],["Rasterise","Convert page content into a pixel image"]])],
 [["Form-field flatten (keeps text)","Yes"],["Full-page flatten","Yes"],["Reports number of fields flattened","Yes"]],
 [Q("What does flatten PDF mean?","It merges form fields and annotations into the page so they can no longer be edited."),
  Q("How do I flatten a PDF?","Drop it here, choose a mode and download the flattened file."),
  Q("Can I flatten a PDF for free?","Yes, with no sign-up or watermark."),
  Q("Does flattening reduce quality?","Form-field mode keeps quality identical; all-content mode renders pages as images."),
  Q("Will text remain searchable?","Yes in form-field mode; no in all-content mode unless you run OCR."),
  Q("Can a flattened PDF be unflattened?","No, keep the original if you may need to edit the form again."),
  Q("Should I flatten before signing?","Fill and flatten first, then sign, so the signature covers the final content."),
  Q("Is my file uploaded?","No, flattening runs in your browser.")],
 [("Fill PDF form","fill-pdf-form"),("Protect PDF","protect-pdf"),("Sign PDF","sign-pdf"),("Compress PDF","compress-pdf"),("OCR PDF","ocr-pdf")])
# ---------- METADATA ----------
T("metadata","Edit PDF Metadata – Title, Author, Keywords Free",
 "Edit PDF metadata free: change title, author, subject, keywords, creator and producer, or strip all metadata for privacy. No upload, no sign-up.",
 [["Edit PDF metadata online",
   "Every PDF carries hidden document properties: a title, author, subject, keywords, the app that created it (creator), the library that wrote it (producer), and creation and modification dates. This tool shows the current values as soon as you open a file, lets you change any of them, and saves a new copy. You can also tick *Strip metadata* to blank every field and remove the XMP metadata block for privacy.",
   "Good metadata matters more than people think. The title is what browsers, PDF viewers and search engines show instead of the file name; the author field can reveal a person's name or a company account; and keywords help document management systems find files."],
  ["Fields you can change",
   {"table":[["Field","What it is","Tip"],["Title","Name shown in viewer title bars and search results","Use a clear, descriptive title, not ‘Microsoft Word – Doc1’"],["Author","Person or organisation","Clear it before publishing if it shows a personal account"],["Subject","Short description","One sentence summary"],["Keywords","Search terms, separated by commas","5–10 relevant terms"],["Creator","App that made the original","Often ‘Microsoft Word’"],["Producer","Software that wrote the PDF","Shows the converter used"]]},
   "The modification date is set to the moment you save. Creation date is kept."],
  ["How to edit PDF metadata for free",
   {"steps":["Drop the PDF – current values appear in the boxes.","Edit any field, or tick Strip metadata.","Press Save and download the updated PDF."]}],
  ["Why strip metadata?",
   "Metadata is a common source of accidental leaks: a contract sent to a client with the author set to a competitor's name, a published report whose properties reveal an employee's username, or a CV that shows the template's original owner. Stripping blanks the title, author, subject, keywords, creator and producer and removes the XMP metadata stream, which often duplicates them. It does not change the visible content – check headers, footers and comments separately, and use [Redact PDF](/redact-pdf/) for sensitive text on the pages."],
  ["Metadata and SEO",
   "Search engines index PDFs and often use the document title from metadata as the result headline. A clear title and subject can improve how your PDF appears in search results and in browser tabs. The keywords field is ignored by major search engines but is used by many document management and library systems."],
  ["Can PDF metadata be edited?",
   "Yes – metadata is just a set of text fields in the file, and changing them does not affect the pages. The only exceptions are PDFs that are encrypted (unlock them first with [Unlock PDF](/unlock-pdf/)) and digitally signed files, where any change, including metadata, invalidates the signature."],
  ["Edit PDF metadata online vs desktop software",
   "Desktop PDF editors and command-line tools such as ExifTool can edit metadata, but they need installing. Most online editors upload the file. Here, the PDF is read and saved in your browser – handy on a work computer where you cannot install software, and safe for confidential files."],
  G([["Metadata","Information about a document, stored separately from its pages"],["XMP","An XML metadata format embedded in many PDFs"],["Document Info dictionary","The classic place PDF metadata is stored"],["Producer","Software that generated the PDF file"]])],
 [["Shows current values","Yes"],["Strip all metadata","Yes"],["Edit creator & producer","Yes"]],
 [Q("How do I edit PDF metadata?","Drop the PDF, change the fields shown and save."),
  Q("Can I edit PDF metadata for free?","Yes, free and without sign-up."),
  Q("How do I change the title of a PDF?","Edit the Title field; it is what viewers and search engines display."),
  Q("Can I remove the author from a PDF?","Yes, clear the Author field or tick Strip metadata."),
  Q("Can I change the creation date?","The creation date is kept; the modification date is updated automatically."),
  Q("Does editing metadata change the content?","No, the pages are untouched."),
  Q("Does it work on signed PDFs?","Changing metadata breaks a digital signature."),
  Q("Is my file uploaded?","No, editing runs locally.")],
 [("Remove PDF metadata","remove-pdf-metadata"),("Redact PDF","redact-pdf"),("Protect PDF","protect-pdf"),("Compress PDF","compress-pdf"),("PDF to PDF/A","pdf-to-pdfa")],
 faqKw=[Q("Can PDF metadata be edited?","Yes. Metadata fields such as title and author are stored separately from the pages, so you can change them without affecting the content – except in digitally signed files.")])

# ---------- REDACT ----------
T("redact","Redact PDF Free – Black Out Text Permanently",
 "Redact PDF free: black out (or white out) text by search, e-mails, phone numbers or drawn boxes. Content is permanently removed, not hidden. No upload.",
 [["Redact a PDF for free – real removal, not a black box on top",
   "Redaction means permanently removing sensitive information – names, account numbers, addresses, signatures – before you share a document. The most common mistake is drawing black rectangles in an ordinary PDF editor: the text underneath is still there and can be copied out. This tool does real redaction. Every page that contains a redaction is rebuilt as an image with the boxes burned in, so the hidden text, its font data and any selectable layer underneath are gone. Pages without redactions are copied untouched, and document metadata is cleared.",
   "You can redact by **searching** for words or phrases (comma-separated, e.g. *John Smith, 4111 1111*), by automatically finding **all e-mail addresses** and **phone numbers**, or by **drawing boxes** over anything – photos, signatures, stamps, handwriting – on the page preview."],
  ["How to black out text on a PDF",
   {"steps":["Drop the PDF.","Type words to redact, and/or tick e-mails and phone numbers.","Draw boxes on the preview for anything else; use the page buttons to move between pages.","Choose black or white boxes and press Redact.","Download and check the redacted copy."]}],
  ["Black or white redaction?",
   "Black boxes are the convention for legal and government documents because they make it obvious that something was removed. White boxes (sometimes called *white-out redaction*) blend into the page and are used when a clean look matters, for example in published examples or templates. Both remove the content equally."],
  ["Is there a way to redact text in a PDF without Adobe Pro?",
   "Yes – that is exactly what this page does, free and in your browser. Professional suites offer the same kind of true redaction in their paid editions; free viewers and many basic editors only offer drawing shapes, which is not redaction."],
  ["What happens to redacted pages",
   {"table":[["","Pages with redactions","Other pages"],["Content","Rendered at high resolution (≈180 dpi) with boxes burned in","Copied exactly"],["Text selectable","No (run OCR if needed)","Yes"],["Hidden text recoverable","No","—"],["Metadata","Cleared for the whole document","Cleared"]]},
   "If you need the redacted pages to be searchable again, run [OCR PDF](/ocr-pdf/) on the result – the redacted areas contain no text, so nothing sensitive comes back."],
  ["Search tips",
   {"list":["Separate several terms with commas.","Leave *Match case* off to catch SMITH, Smith and smith.","Search finds real text only; for scanned pages, draw boxes or run OCR first.","Numbers formatted differently (4111-1111 vs 4111 1111) need each format listed.","Always review every page of the result before sharing."]}],
  ["Can I redact a PDF that has been signed?",
   "You can, but redacting changes the document, so any digital signature becomes invalid. Redact first, then sign the final version."],
  ["Other places sensitive data hides",
   "Comments, form fields, attachments, bookmarks and layers can also contain personal data. Redacted pages are rebuilt without them; for the rest of the document, consider [Flatten PDF](/flatten-pdf/) and [Remove PDF metadata](/remove-pdf-metadata/)."],
  G([["Redaction","Permanent removal of information from a document"],["Burn in","Make a mark part of the page image itself"],["OCR","Recognising text in an image to make it searchable"],["PII","Personally identifiable information"]])],
 [["True removal (not overlay)","Yes"],["Auto-find e-mails & phone numbers","Yes"],["Black or white boxes","Yes"],["Draw boxes on any page","Yes"]],
 [Q("How can I redact a PDF for free?","Drop it here, search for terms or draw boxes, and download the redacted PDF – no sign-up."),
  Q("How do I black out text on a PDF?","Type the text or draw a box over it and press Redact; the text is permanently removed."),
  Q("What does redact PDF mean?","Permanently removing sensitive content so it cannot be recovered."),
  Q("Is the redaction permanent?","Yes, affected pages are rebuilt as images without the hidden text."),
  Q("Can I redact e-mail addresses automatically?","Yes, tick the e-mail and phone number options."),
  Q("Can I use white instead of black?","Yes, choose white boxes."),
  Q("Will redacted pages be searchable?","Not until you run OCR on them."),
  Q("Is my document uploaded?","No, redaction happens on your device.")],
 [("Remove PDF metadata","remove-pdf-metadata"),("Flatten PDF","flatten-pdf"),("OCR PDF","ocr-pdf"),("Protect PDF","protect-pdf"),("Edit PDF","edit-pdf")])
# ---------- COMPARE ----------
T("compare","Compare PDF – Find Differences Between Two PDFs",
 "Compare two PDF files side by side and highlight added, deleted and changed text word by word. Download the report. Free, no upload, no sign-up.",
 [["Compare two PDF documents for differences",
   "Compare PDF shows exactly what changed between two versions of a document. Drop the original and the revised PDF, and the text of both is lined up side by side: deleted lines are highlighted red on the left, added lines green on the right, and changed lines yellow with the exact words struck through or inserted. A summary shows the number of deletions, additions and changes, and you can download the comparison as an HTML report to share or archive.",
   "It is the quickest way to check a contract redline, confirm that only the agreed clauses were changed in a new policy, review edits to a thesis, or spot differences between two invoices or quotes."],
  ["How to compare two PDF files",
   {"steps":["Drop both PDFs (original first, then revised).","Press Compare.","Read the side-by-side table: red = removed, green = added, yellow = changed.","Download the HTML report if you need to keep or send it."]}],
  ["What is compared",
   "The tool compares the **text** of the documents line by line, then word by word within changed lines, and shows the page number of every line. That makes it ideal for contracts, reports, policies and other text documents. Formatting changes (font, colour, layout) and image changes are not detected, and scanned PDFs need [OCR PDF](/ocr-pdf/) first so they contain text."],
  ["Reading the result",
   {"table":[["Colour","Meaning"],["Red, left column","Line exists only in the first PDF (deleted)"],["Green, right column","Line exists only in the second PDF (added)"],["Yellow, both columns","Line changed; struck-through words were removed, highlighted words added"],["No colour","Unchanged"]]}],
  ["Can I compare a PDF and a Word document?",
   "Convert the Word file to PDF first with [Word to PDF](/word-to-pdf/), then compare the two PDFs. Alternatively convert the PDF to Word with [PDF to Word](/pdf-to-word/) and use Word's built-in compare feature."],
  ["Tips for accurate comparisons",
   {"list":["Compare documents produced the same way – two exports from Word compare more cleanly than a Word export against a scan.","Re-flowed text (a paragraph that moves to a new page) still matches, because comparison follows the text, not the page.","Headers and footers appear as lines too; changed page numbers can show as small changes.","For long documents, use your browser's find (Ctrl+F) in the report to jump to a clause."]}],
  ["Compare PDF online vs desktop software",
   "Professional PDF suites and dedicated comparison apps offer visual comparison in paid plans, and online tools typically upload both documents. Here, both files are read in your browser and never leave your device – important when comparing confidential contracts."],
  G([["Diff","A list of differences between two texts"],["Redline","A marked-up version showing changes"],["Word-level diff","Highlighting exactly which words changed in a line"]])],
 [["Word-level highlighting","Yes"],["Downloadable report","Yes (HTML)"],["Page numbers per line","Yes"]],
 [Q("How can I compare two PDF files?","Drop both PDFs and press Compare to see differences side by side."),
  Q("Can I compare two PDF documents for differences for free?","Yes, free and without sign-up."),
  Q("Does it highlight changes?","Yes: red removed, green added, yellow changed with word-level marks."),
  Q("Can it compare scanned PDFs?","Run OCR first so the pages contain text."),
  Q("Are images compared?","No, only text is compared."),
  Q("Can I save the comparison?","Yes, download the HTML report."),
  Q("Can I compare a PDF with a Word file?","Convert the Word file to PDF first."),
  Q("Are my files uploaded?","No, comparison runs locally.")],
 [("PDF to Word","pdf-to-word"),("Word to PDF","word-to-pdf"),("OCR PDF","ocr-pdf"),("Find and replace in PDF","find-and-replace-pdf"),("Merge PDF","merge-pdf")])
# ---------- DESKEW ----------
T("deskew","Deskew PDF – Straighten Scanned Pages Free",
 "Deskew scanned PDFs automatically: detects the tilt of each page and straightens it, leaving straight pages untouched. Free, no upload, no sign-up.",
 [["What does deskew mean?",
   "A skewed page is one that was scanned or photographed slightly crooked – tilted by a degree or two, so lines of text slope across the page. Deskewing detects that angle and rotates the page back so text runs perfectly horizontal. Deskew PDF does this automatically for every page of a scanned document, measuring each page separately, and reports the angle it found for each one.",
   "Straight pages are easier to read, look more professional, print better, compress smaller and – importantly – give much more accurate OCR results."],
  ["How to deskew a scanned PDF",
   {"steps":["Drop the scanned PDF.","Optionally change the maximum angle to look for (default 10°).","Press Deskew.","Download the straightened PDF; the result lists the angle corrected on each page."]}],
  ["How the angle is detected",
   "Each page is rendered and analysed with a projection-profile method: the tool tries small rotation angles and measures how sharply the rows of dark pixels line up. Text lines produce the strongest, most regular pattern when they are perfectly horizontal, so the best-scoring angle is the skew. This works for typed documents, forms and books. Pages whose detected tilt is below 0.15° are considered straight and are copied untouched, keeping their original quality and selectable text."],
  ["Deskew vs rotate",
   {"table":[["Problem","Tool"],["Page tilted a few degrees","Deskew PDF"],["Page sideways or upside down (90°/180°)","[Rotate PDF](/rotate-pdf/)"],["Pages in the wrong order","[Organize PDF](/organize-pdf/)"],["Extra borders after straightening","[Crop PDF](/crop-pdf/)"]]}],
  ["What happens to straightened pages",
   "Tilted pages are re-rendered at high resolution (≈144 dpi) and rotated, with white filling the corners that the rotation reveals. Because they become images, any existing text layer on those pages is not kept – run [OCR PDF](/ocr-pdf/) afterwards to make them searchable, which will now be more accurate. Straight pages are copied without change."],
  ["Maximum angle",
   "The default search range of ±10° covers almost every scanner and phone photo. Lower it to 3–5° for speed on long documents that are only slightly crooked; raise it (up to 20°) for badly placed photos. Pages that are mostly pictures or have little text may not have a clear line pattern and can be left as they are."],
  ["Tips for better scans",
   {"list":["Align paper against the scanner glass edge.","Use the feeder guides snugly.","Photograph documents from directly above.","Scan at 200–300 dpi for text documents.","After deskewing, crop and compress to tidy up the file."]}],
  ["Deskew PDF online vs desktop software",
   "Deskewing is found in scanner software and paid OCR suites. Online services upload your scans – often personal documents like IDs and bank letters. Here it runs in your browser, for free."],
  G([["Skew","A small tilt of the page content"],["Deskew","Rotate to remove the tilt"],["Projection profile","Sum of dark pixels per row, used to detect text lines"],["OCR","Recognising text in a page image"]])],
 [["Automatic per-page angle","Yes"],["Straight pages left untouched","Yes"],["Reports angle per page","Yes"]],
 [Q("What does deskew mean?","Straightening a page that was scanned at a slight angle."),
  Q("How do I deskew a scanned PDF?","Drop it here and press Deskew; each page is straightened automatically."),
  Q("Is it free?","Yes, with no sign-up."),
  Q("Does it work on photos of documents?","Yes, if the page contains lines of text."),
  Q("Will text stay selectable?","Straightened pages become images; run OCR to make them searchable."),
  Q("Can it fix upside-down pages?","Use Rotate PDF for 90° and 180° turns."),
  Q("Does deskewing improve OCR?","Yes, straight text is recognised much more accurately."),
  Q("Is my PDF uploaded?","No, all processing is local.")],
 [("OCR PDF","ocr-pdf"),("Rotate PDF","rotate-pdf"),("Crop PDF","crop-pdf"),("Compress PDF","compress-pdf"),("PDF scanner","pdf-scanner")])

# ---------- HEADER FOOTER ----------
T("headerfooter","Add Header and Footer to PDF – Free, Page X of Y",
 "Add headers and footers to PDF: left, centre and right text with page numbers, total, date and file name, skip first pages, colour. Free, no upload.",
 [["Add a header and footer to a PDF",
   "This tool adds text to the top and bottom of every page of a PDF – six positions in all: header left, centre and right, and footer left, centre and right. Type plain text such as *Confidential* or a company name, or use placeholders that change on each page: **{page}** for the page number, **{total}** for the page count, **{date}** for today's date and **{file}** for the file name. The default footer *{page} / {total}* gives you ‘Page X of Y’ numbering instantly.",
   "Headers and footers make documents easier to navigate and cite, mark drafts and confidential files, and add branding to reports and proposals – without going back to the original Word or design file."],
  ["How to add a header and footer to a PDF for free",
   {"steps":["Drop one or more PDFs.","Type text into any of the six boxes, using placeholders if you like.","Set font size, margin, colour, pages to skip and the first page number.","Press the button and download (several files come as a ZIP)."]}],
  ["Placeholder examples",
   {"table":[["You type","Page 3 of 10 shows"],["{page} / {total}","3 / 10"],["Page {page} of {total}","Page 3 of 10"],["{file} – {date}","report.pdf – 2026-10-25"],["Draft v2 – {date}","Draft v2 – 2026-10-25"],["Confidential","Confidential"]]}],
  ["Skip the cover and start numbering where you want",
   "Set *Skip first pages* to leave the cover (or cover and contents) without a header or footer. *First page number* sets the number printed on the first page that receives one – so with 2 pages skipped and first number 1, page 3 of the file shows ‘1’. The {total} placeholder counts only the numbered pages, so ‘Page 1 of 8’ stays consistent."],
  ["Fonts, size and colour",
   "Text is drawn in a clean sans-serif font. Characters outside the basic Latin set – accents, Cyrillic, Greek and many other scripts – are rendered with a matching Unicode font loaded on demand. Choose a size from 6 to 36 pt, the distance from the page edge (margin) in points, and any text colour; dark grey is the default because it looks less heavy than pure black."],
  ["Header/footer vs page numbers vs Bates",
   {"table":[["Need","Best tool"],["Text plus page numbers in any position","Add header and footer (this page)"],["Only page numbers, roman numerals, facing pages","[Add page numbers](/add-page-numbers/)"],["Legal sequential IDs across many files","[Bates numbering](/bates-numbering/)"],["Diagonal ‘DRAFT’ across the page","[Add watermark](/add-watermark-to-pdf/)"]]}],
  ["Can I remove or edit an existing header?",
   "Headers that were added to a PDF become part of the page content, so they cannot be switched off like in Word. To hide an old header, crop it away with [Crop PDF](/crop-pdf/) or cover it with white-out in [Edit PDF](/edit-pdf/), then add a new header here."],
  ["Add header and footer online vs desktop software",
   "Paid PDF editors include header/footer tools, and Word can add them before export – if you still have the source file. Online alternatives upload your document. This tool works on the finished PDF, in your browser, free."],
  G([["Header","Text at the top of every page"],["Footer","Text at the bottom of every page"],["Placeholder","A code such as {page} replaced with a value on each page"],["Point (pt)","1/72 inch; the unit for font size and margins"]])],
 [["Six positions","Yes"],["{page} {total} {date} {file}","Yes"],["Skip first pages / start number","Yes"],["Text colour","Yes"],["Batch files","Yes"]],
 [Q("How do I add a header and footer to a PDF?","Type text in the header or footer boxes, set size and margin, and download."),
  Q("Can I add page X of Y?","Yes, use {page} / {total} or Page {page} of {total}."),
  Q("Is it free?","Yes, with no sign-up or watermark."),
  Q("Can I skip the first page?","Yes, set Skip first pages to 1."),
  Q("Can I add the date?","Yes, use {date}."),
  Q("Can I change the colour?","Yes, pick any text colour."),
  Q("Can I process several PDFs?","Yes, drop multiple files to get a ZIP."),
  Q("Is my PDF uploaded?","No, it is processed in your browser.")],
 [("Add page numbers","add-page-numbers"),("Bates numbering","bates-numbering"),("Add watermark","add-watermark-to-pdf"),("Edit PDF","edit-pdf"),("Crop PDF","crop-pdf")],
 faqKw=[Q("How do I insert a header and footer in a PDF without Word?","Use this tool on the finished PDF: type the header and footer text, choose positions, and download – no need for the original Word file.")])
# ---------- BATES ----------
T("bates","Bates Numbering PDF Free – Prefix, Digits, Batch",
 "Add Bates numbers to PDFs free: prefix, start number, digits, suffix and position, numbered continuously across many files. No upload, no sign-up.",
 [["What is Bates numbering?",
   "Bates numbering gives every page in a set of legal or business documents a unique, sequential identifier – for example **ABC000001**, **ABC000002**, and so on. It is used in litigation discovery, regulatory submissions, audits and large document productions so that any page can be cited and found precisely (‘see ABC004187’). The name comes from the Bates automatic numbering machine, a mechanical stamper patented in the 1890s that advanced one number with every press.",
   "This tool stamps Bates numbers digitally on PDFs. Drop one or many files, set the prefix, starting number, number of digits, optional suffix and position, and every page is numbered in sequence – continuing from one file to the next."],
  ["Bates numbering example",
   {"table":[["Setting","Value"],["Prefix","SMITH-"],["Start","1"],["Digits","6"],["Suffix","-CONF"],["Result, first page","SMITH-000001-CONF"],["Result, page 250","SMITH-000250-CONF"]]},
   "If the first file has 120 pages, the second file starts at 000121 automatically. The result message shows the full range applied, e.g. *SMITH-000001 – SMITH-000534*."],
  ["How to add Bates numbers to a PDF for free",
   {"steps":["Drop the PDFs in the order they should be numbered.","Enter prefix, start number, digits and optional suffix.","Choose the position (bottom right is the convention) and font size.","Press the button and download the numbered PDF or ZIP."]}],
  ["Continuing a previous production",
   "Productions often come in several batches. Note the last number you used (shown in the result), and next time set *Start* to the following number. Keep the same prefix and digit count so the numbering stays consistent across the whole case."],
  ["Best practice",
   {"list":["Use a short, meaningful prefix – a party or case code.","Use 6–8 digits so numbers sort correctly and never run out.","Bottom right is customary; make sure it does not cover existing content, and use a smaller font if needed.","Number final versions only – redact first with [Redact PDF](/redact-pdf/), then apply Bates numbers.","Keep a log of ranges per production."]}],
  ["Can you remove Bates numbering from a PDF?",
   "Bates numbers added here become part of the page content, as they would with a physical stamp, so they are not a separate layer you can turn off. Keep un-numbered originals. If you must hide a number, crop or white it out, but in legal contexts altering produced documents is usually not acceptable."],
  ["Bates numbering vs page numbers",
   "Page numbers restart in each document and describe position within it. Bates numbers are unique across an entire collection, never repeat, and identify a specific page in a production. For ordinary page numbering use [Add page numbers](/add-page-numbers/)."],
  ["Bates numbering online vs desktop software",
   "Bates stamping is usually found in paid professional PDF software and litigation-support tools. Online services require uploading privileged documents. This tool numbers files in your browser for free, without anything leaving your computer."],
  G([["Bates number","Unique sequential page identifier"],["Production","A set of documents handed over in litigation"],["Prefix / suffix","Fixed text before or after the number"],["Discovery","Exchange of evidence between parties"]])],
 [["Continuous across files","Yes"],["Prefix, suffix, digits","Yes"],["Shows range applied","Yes"]],
 [Q("What is Bates numbering?","A unique sequential number on every page of a document set, used in legal work."),
  Q("How can I add Bates numbers to a PDF for free?","Drop the PDFs, set prefix, start and digits, and download."),
  Q("Does numbering continue across files?","Yes, the next file continues the sequence."),
  Q("What is a Bates numbering example?","ABC000001, ABC000002 … with prefix ABC and 6 digits."),
  Q("Where should Bates numbers go?","Bottom right is the usual convention."),
  Q("Can I remove Bates numbers?","They become part of the page; keep un-numbered originals."),
  Q("Can I add a suffix like CONFIDENTIAL?","Yes, use the suffix field."),
  Q("Are my files uploaded?","No, numbering happens on your device.")],
 [("Add page numbers","add-page-numbers"),("Redact PDF","redact-pdf"),("Add header and footer","pdf-header-footer"),("Merge PDF","merge-pdf"),("Flatten PDF","flatten-pdf")])

# ---------- FIND & REPLACE ----------
T("findreplace","Find and Replace Text in PDF Online Free",
 "Find and replace text in a PDF free: replace a word, name or date everywhere, several pairs at once, match case. Runs in your browser, no upload.",
 [["Find and replace text in a PDF",
   "Find and replace in PDF searches every page of a document for a word or phrase and replaces each occurrence with new text – the same thing you would do with Ctrl+H in Word, but on a finished PDF. It is ideal for fixing a misspelt name throughout a brochure, updating a year in a price list from 2025 to 2026, changing a phone number on a flyer, or swapping a placeholder like *[CLIENT]* in a template. Add extra pairs, one per line (*old => new*), to make several replacements in one pass.",
   "Leave the *Replace* box empty to simply remove the matching text, and keep *Match case* on to avoid changing words that only look similar."],
  ["How to find and replace text in a PDF file",
   {"steps":["Drop the PDF on this page.","Type the text to find and the replacement.","Optionally add more pairs, one per line, such as 2025 => 2026.","Choose Match case, press the button, and download the edited PDF. The result shows how many replacements were made."]}],
  ["How it works – and why PDFs are different from Word",
   "A Word document stores text as flowing paragraphs. A PDF stores the *final layout*: each piece of text is placed at exact coordinates, often split into small runs, in a font that may contain only the characters used in the document. There is no paragraph that can reflow. That is why genuine find-and-replace inside a PDF is hard and why many tools do not offer it at all.",
   "This tool takes a practical, visual approach. It reads the text and its positions with PDF.js, finds every match, covers the original characters with a white box exactly the size of the match, and writes the replacement text in the same position and size. The page looks updated, prints correctly and the new text is selectable and searchable."],
  ["What it handles well",
   {"list":["Names, numbers, dates, codes and short phrases.",
    "Replacements of similar length – *2025* → *2026*, *Ltd* → *LLC*.",
    "Text on plain white backgrounds.",
    "Horizontal text in common fonts.",
    "Many occurrences across many pages, in one pass."]}],
  ["Limitations to know about",
   {"table":[["Situation","What happens","What to do"],["Replacement much longer than original","New text may overlap the following words","Keep length similar, or use [Edit PDF](/edit-pdf/) to adjust"],["Coloured or image background","White box is visible behind the new text","Edit that page manually in Edit PDF"],["Rotated or vertical text","Skipped","Edit manually"],["Text split across lines or runs","Phrase may not be found","Search for a shorter part"],["Scanned PDF (image of text)","Nothing found","Run [OCR PDF](/ocr-pdf/) first, then edit"],["Special decorative fonts","Replacement uses a standard font","Accept, or edit manually"]]},
   "The original text is covered, not deleted from the file. For confidential text that must be gone, use [Redact PDF](/redact-pdf/) instead."],
  ["Can you Ctrl+F in a PDF?",
   "Yes – every PDF viewer, including your browser, can *find* text with Ctrl+F (Cmd+F on Mac), as long as the PDF has real text and not just scanned images. Finding is easy; *replacing* is what most viewers cannot do, because it requires changing the page content. This tool adds that missing step."],
  ["How to overtype text in a PDF",
   "For a single change in one spot, [Edit PDF](/edit-pdf/) is often better: click the text, type over it, and adjust font, size and position by eye. Use find and replace when the same change is needed in many places, or when you want to be sure you caught every occurrence."],
  ["Replacing several terms at once",
   "The extra pairs box accepts one replacement per line in the form *old => new*. For example:",
   {"list":["*Acme Ltd => Acme LLC*","*2025 => 2026*","*+44 20 7946 0000 => +44 20 7946 0999*"]},
   "Each pair is applied to every page. The main Find/Replace boxes count as the first pair. Lines without *=>* are ignored."],
  ["Getting the best match on fonts",
   "Replacement text is drawn in a standard sans-serif font at the size of the original text, in black. For documents set in a similar font – Arial, Helvetica, Calibri, many corporate fonts – the change is barely noticeable. For serif or decorative typefaces, the new word will look slightly different; for headlines or logos, editing in the original design file gives the best result. Non-Latin characters in the replacement are supported via an automatically loaded Unicode font."],
  ["Typical uses",
   {"list":["**Price lists and menus** – update years, prices or product names.",
    "**Brochures and flyers** – change a phone number, address or website.",
    "**Templates** – fill placeholders like [NAME] or [DATE].",
    "**Certificates** – correct a misspelt name before printing.",
    "**Reports** – update a company name after a rebrand.",
    "**Forms** – fix a typo in a label without the source file."]}],
  ["When you have the original document",
   "If you have the source Word, Excel or InDesign file, edit there and export a new PDF – that always gives perfect typography and reflowing text. Find and replace in PDF is for when you only have the PDF, need a quick fix, or the source file is lost. You can also convert to Word with [PDF to Word](/pdf-to-word/), use Word's own replace, and convert back with [Word to PDF](/word-to-pdf/); that works well for text documents but may change complex layouts."],
  ["Checking your result",
   "The result tells you how many replacements were made. Open the PDF and check a few: look at line ends where a longer replacement might overlap following words, and pages with coloured backgrounds. If something looks wrong, adjust the text and run again on the original file – your source PDF is never modified. You can also [compare](/compare-pdf/) the original and edited versions to see every change side by side."],
  ["Find and replace in PDF online vs desktop editors",
   "Professional PDF editors offer find-and-replace with true text editing, usually in paid editions. Free viewers do not offer replacement at all, and online editors generally upload your file. This tool gives you multi-pair replacement for free, in your browser, with nothing uploaded – useful for contracts, price lists and internal documents."],
  ["Is it safe for confidential documents?",
   "Yes, in the sense that the file never leaves your device. But remember that replaced text is visually covered rather than removed from the file's content stream, so someone with a PDF editor could still find the old text. For anything sensitive – names in legal documents, account numbers, personal data – use [Redact PDF](/redact-pdf/), which permanently removes content."],
  G([["Text run","A piece of text placed at one position in a PDF"],["Content stream","The instructions that draw a PDF page"],["Reflow","Text moving to fit after edits; PDFs do not reflow"],["Match case","Only match identical capitalisation"],["Subset font","Font embedded with only the characters used"]])],
 [["Multiple replacement pairs at once","Yes"],["Match case","Yes"],["Reports replacement count","Yes"],["Works offline","Yes"]],
 [Q("How do I find and replace text in a PDF?","Type the text to find and the replacement, press the button and download the edited PDF."),
  Q("Can I find and replace in a PDF for free?","Yes, free with no sign-up or watermark."),
  Q("Can I replace several words at once?","Yes, add pairs one per line as old => new."),
  Q("Does it keep the same font?","It uses a standard font at the original size; similar sans-serif fonts look almost identical."),
  Q("Does it work on scanned PDFs?","Run OCR first; scanned pages contain no text to find."),
  Q("Is the old text deleted?","It is covered. Use Redact PDF to remove sensitive text permanently."),
  Q("Can I remove text instead of replacing it?","Yes, leave the Replace box empty."),
  Q("Is my PDF uploaded?","No, the edit runs in your browser.")],
 [("Edit PDF","edit-pdf"),("Redact PDF","redact-pdf"),("Compare PDF","compare-pdf"),("PDF to Word","pdf-to-word"),("OCR PDF","ocr-pdf")],
 faqKw=[Q("How do I replace text in a PDF with the same font?","Exact font matching is only possible when the PDF embeds the full font. This tool writes replacements in a clean sans-serif at the original size, which closely matches common fonts like Arial and Helvetica.")])

from ed2 import X
for k,v in X.items():
    sec=S[k]["sections"];i=[j for j,x in enumerate(sec) if x[0]=="Privacy"][0];S[k]["sections"]=sec[:i]+v+sec[i:]
